// Best-effort HMAC verification. Django signs X-Signature = HMAC-SHA256(
// N8N_SHARED_SECRET, raw compact JSON body). NOTE: n8n's raw-body access varies
// by version, so this is observability-only and does NOT block delivery — enforce
// signatures with n8n native Header Auth or a network control in production.
const crypto = require('crypto');
const secret = $env.N8N_SHARED_SECRET || '';
const items = $input.all();
let headers = {};
try { headers = ($input.first().json.headers) || {}; } catch (e) {}
const sig = headers['x-signature'] || headers['X-Signature'] || '';
let raw = '';
try {
  const j = $input.first().json;
  raw = (typeof j.body === 'string') ? j.body : JSON.stringify(j.body != null ? j.body : j);
} catch (e) { raw = ''; }
let valid = false;
try {
  if (secret && sig && raw) {
    const expected = crypto.createHmac('sha256', secret).update(raw, 'utf8').digest('hex');
    valid = (expected.length === sig.length) &&
            crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(sig));
  }
} catch (e) { valid = false; }
return items.map(it => ({ json: Object.assign({}, it.json, { _signature_valid: valid }) }));

// Internal alert email (English). Handles internal.alert and margin.negative.
const p = $input.first().json;
const d = p.data || {};
const ev = p.event || 'internal.alert';
const sym = { EUR: '€', USD: '$', GBP: '£' }[d.currency] || (d.currency ? d.currency + ' ' : '');

let subject, bodyRows;
if (ev === 'margin.negative') {
  subject = `[Negative Margin] ${d.subject || ('Order ' + (d.order_number || ''))}`;
  const margin = (d.net_margin != null) ? sym + Number(d.net_margin).toFixed(2) : '-';
  bodyRows = `<li><strong>Order:</strong> ${d.order_number || '-'}</li>
<li><strong>Net margin:</strong> <span style="color:#b00020">${margin}</span></li>`;
} else {
  subject = `[Internal Alert] ${d.subject || 'Glitchy'}`;
  // Render any extra fields generically (never secrets — keys are operational).
  bodyRows = Object.keys(d).filter(k => k !== 'subject').map(k => `<li><strong>${k}:</strong> ${typeof d[k] === 'object' ? JSON.stringify(d[k]) : d[k]}</li>`).join('') || '<li>(no additional data)</li>';
}

const html = `<div style="font-family:Arial,Helvetica,sans-serif;max-width:640px;color:#222">
<h2 style="color:#111">${subject}</h2>
<ul>${bodyRows}</ul>
<p style="color:#666">Automated internal notification from Glitchy.</p>
</div>`;

return [{ json: { to: $env.ADMIN_NOTIFY_EMAIL, subject, html } }];
